{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Dampen repeated items using causal prefix counts: scale each existing input embedding by 1/sqrt(1 + 0.1*c), excluding padding and the current occurrence. Training and inference share this feature through the model class imported by the predictor writer. Embeddings, GRU topology, readout, loss, optimizer, and dataset routing remain unchanged.",
      "edits": [
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))\n",
          "replace": "    def _input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.item_emb(seq)\n        with torch.no_grad():\n            same_item = seq.unsqueeze(2).eq(seq.unsqueeze(1))\n            earlier_counts = torch.tril(same_item, diagonal=-1).sum(dim=-1)\n            earlier_counts = earlier_counts.masked_fill(seq.eq(0), 0)\n            scale = (1.0 + 0.1 * earlier_counts.to(dtype=emb.dtype)).rsqrt()\n        return self.dropout(emb * scale.unsqueeze(-1))\n\n    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self._input_embeddings(seq)\n"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))\n",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self._input_embeddings(seq)\n"
        }
      ]
    }
  ],
  "change_summary": "Add deterministic causal repetition damping to GRU inputs for all four category models. The generated predictor automatically uses the updated model class."
}
